USE order_inventory;
CREATE TABLE IF NOT EXISTS inventory_stock(sku_id BIGINT PRIMARY KEY,total_stock INT NOT NULL,available_stock INT NOT NULL,reserved_stock INT NOT NULL,sold_stock INT NOT NULL,version INT NOT NULL DEFAULT 0,create_time DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),update_time DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),CONSTRAINT chk_stock_nonnegative CHECK(available_stock>=0 AND reserved_stock>=0 AND sold_stock>=0),CONSTRAINT chk_stock_conservation CHECK(total_stock=available_stock+reserved_stock+sold_stock)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS inventory_reservation(id BIGINT PRIMARY KEY,reservation_no VARCHAR(64) NOT NULL,order_no VARCHAR(64) NOT NULL,user_id BIGINT NOT NULL,sku_id BIGINT NOT NULL,quantity INT NOT NULL,status TINYINT NOT NULL,expire_time DATETIME(3) NOT NULL,version INT NOT NULL DEFAULT 0,create_time DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),update_time DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),UNIQUE KEY uk_reservation_no(reservation_no),UNIQUE KEY uk_order_sku(order_no,sku_id),KEY idx_expire_status(expire_time,status),KEY idx_order_no(order_no)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS inventory_change_log(id BIGINT PRIMARY KEY,sku_id BIGINT NOT NULL,order_no VARCHAR(64),reservation_no VARCHAR(64),operation_type VARCHAR(32) NOT NULL,quantity INT NOT NULL,before_available INT,after_available INT,create_time DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),KEY idx_sku_time(sku_id,create_time),KEY idx_order_no(order_no)) ENGINE=InnoDB;
